class Solution:
    def toGoatLatin(self, sentence: str) -> str:
        vowels = set('aeiouAEIOU')
        res = []
        for i, w in enumerate(sentence.split(), 1):
            if w[0] not in vowels:
                w = w[1:] + w[0]
            w += 'ma' + 'a' * i
            res.append(w)
        return ' '.join(res)

