class Solution {
public:
    string toGoatLatin(string sentence) {
        unordered_set<char> vowels{'a','e','i','o','u','A','E','I','O','U'};
        stringstream ss(sentence);
        string w, res;
        int idx = 1;
        while (ss >> w) {
            if (!vowels.count(w[0]))
                w = w.substr(1) + w[0];
            w += "ma" + string(idx, 'a');
            if (!res.empty()) res += ' ';
            res += w;
            idx++;
        }
        return res;
    }
};

