class Solution {
public:
    string toGoatLatin(string sentence) {
        auto isVowel = [](char c){ c=tolower(c); return c=='a'||c=='e'||c=='i'||c=='o'||c=='u'; };
        string res;
        int idx = 1, start = 0, n = sentence.size();
        for (int i = 0; i <= n; i++) {
            if (i == n || sentence[i] == ' ') {
                string w = sentence.substr(start, i - start);
                if (!isVowel(w[0])) { char f = w[0]; w.erase(0,1); w += f; }
                w += "ma" + string(idx, 'a');
                if (!res.empty()) res += ' ';
                res += w;
                idx++;
                start = i + 1;
            }
        }
        return res;
    }
};

