class Solution {
    public String toGoatLatin(String sentence) {
        StringBuilder sb = new StringBuilder();
        int idx = 1, start = 0, n = sentence.length();
        for (int i = 0; i <= n; i++) {
            if (i == n || sentence.charAt(i) == ' ') {
                String w = sentence.substring(start, i);
                char c = Character.toLowerCase(w.charAt(0));
                if (c != 'a' && c != 'e' && c != 'i' && c != 'o' && c != 'u')
                    w = w.substring(1) + w.charAt(0);
                sb.append(w).append("ma");
                for (int j = 0; j < idx; j++) sb.append('a');
                sb.append(' ');
                idx++;
                start = i + 1;
            }
        }
        return sb.toString().trim();
    }
}

